<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Resguardo {{$resguardo->Id_Resguardo}}</title><style>body{font-family:Arial,sans-serif;margin:32px;color:#172033}header{display:flex;justify-content:space-between;border-bottom:3px solid #172033;padding-bottom:16px}h1{margin:0}.meta{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:20px 0}table{width:100%;border-collapse:collapse}th,td{border:1px solid #9aa3b2;padding:8px;font-size:12px}th{background:#eef1f5}.ok{color:#16784b}.bad{color:#b42318}.sign{display:grid;grid-template-columns:1fr 1fr;gap:80px;margin-top:70px}.line{border-top:1px solid #333;text-align:center;padding-top:8px}@media print{.no-print{display:none}body{margin:15mm}}</style></head><body><button class="no-print" onclick="window.print()">Imprimir / Guardar PDF</button><header><div><h1>RESGUARDO DE REVISIÓN DE INVENTARIO</h1><div>Sistema de Control de Inventario</div></div><strong>No. {{$resguardo->Id_Resguardo}}</strong></header><div class="meta"><div><b>Periodo:</b> {{$resguardo->periodo->Nombre}}</div><div><b>Estado:</b> {{$resguardo->Cerrado?'CERRADO':'ABIERTO'}}</div><div><b>Ubicación:</b> {{$resguardo->ubicacion?->Nombre}} / Edificio {{$resguardo->ubicacion?->Edificio}} / Planta {{$resguardo->ubicacion?->Planta}}</div><div><b>Empleado responsable:</b> {{$resguardo->empleado->Nombre}} {{$resguardo->empleado->Apellido_Paterno}} {{$resguardo->empleado->Apellido_Materno}}</div><div><b>Fecha:</b> {{$resguardo->Fecha_Cierre?->format('d/m/Y H:i') ?: now()->format('d/m/Y')}}</div></div><table><thead><tr><th>#</th><th>Artículo</th><th>Código</th><th>Ubicación</th><th>Resultado</th></tr></thead><tbody>@foreach($resguardo->articulos as $n=>$i)<tr><td>{{$n+1}}</td><td>{{$i->articulo->Descripcion}}</td><td>{{$i->articulo->Codigo_Barras ?: $i->articulo->N_Serie ?: '—'}}</td><td>{{$i->articulo->ubicacion?->Nombre ?: $i->ubicacion?->Nombre}}</td><td class="{{$i->Revisado?'ok':'bad'}}">{{$i->Revisado?'REVISADO':'NO ESCANEADO'}}</td></tr>@endforeach</tbody></table><p><b>Observaciones:</b> {{$resguardo->Observaciones ?: 'Sin observaciones.'}}</p><div class="sign"><div class="line">Empleado / responsable</div><div class="line">Revisor</div></div></body></html>
